MATCH (fa:FlightAccident) 
WHERE fa.name CONTAINS "FlyMontserrat Flight 107" 
RETURN fa.location AS accident_location;

MATCH (m:AircraftModel)
WHERE m.name CONTAINS "MD-80" OR any(a IN m.aliases WHERE a CONTAINS "MD-80")
RETURN toFloat(m.wingspan_metre) AS wingspan_in_meters;

MATCH (a:AircraftModel)-[:manufacturedBy]->(m:AircraftManufacturer)
WHERE m.name = 'Bombardier'
RETURN a.name AS aircraft_model_name;

MATCH (f:FlightAccident)-[:operatedBy]->(o:Operator) 
WHERE o.name = "ADC Airlines" 
RETURN f.name AS accident_name, f.number_of_deaths AS death_toll;

MATCH (target:FlightAccident {flight_number: "BOAC Flight 911"})-[:destinedFor]->(dest:Airport)
MATCH (other:FlightAccident)-[:departsFrom]->(dest)
RETURN COLLECT(DISTINCT other.name) AS accident_names;

MATCH (fa:FlightAccident)
WHERE fa.flight_number = 'FlyMontserrat Flight 107'
RETURN fa.number_of_survivors AS survivors;

