WHERE op.name = 'Air New Zealand' AND ap.name = 'Auckland Airport'
RETURN DISTINCT fa.name AS accident_name;

MATCH (fa:FlightAccident)-[:departsFrom]->(a:Airport),
      (fa)-[:destinedFor]->(a)
RETURN DISTINCT a.name AS airport_name;

MATCH (fa:FlightAccident | FlightIncident | AircraftCrash)-[*]->(a:Airport) 
WHERE fa.description =~ '(?i).*habyarimana.*' OR fa.description =~ '(?i).*ntaryamira.*' 
RETURN DISTINCT a.name AS destinationAirport;

